import{_ as a,c as t,o as s,aj as r}from"./chunks/framework.Id7s26SP.js";const g=JSON.parse('{"title":"Class: AgentSessionList","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/classes/AgentSessionList.md","filePath":"reference/js-bao-wss-client/api/classes/AgentSessionList.md"}'),o={name:"reference/js-bao-wss-client/api/classes/AgentSessionList.md"};function n(i,e,c,h,d,l){return s(),t("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / AgentSessionList</p><h1 id="class-agentsessionlist" tabindex="-1">Class: AgentSessionList <a class="header-anchor" href="#class-agentsessionlist" aria-label="Permalink to “Class: AgentSessionList”">​</a></h1><p>A live list of your agent sessions, from <code>client.agents.sessions.watch()</code>. Read <code>items</code> (kept current, newest activity first), call <code>onChange</code> to hear about every change, <code>loadMore()</code> for the next page, and <code>close()</code> when done.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new AgentSessionList</strong>(<code>host</code>, <code>options</code>): <code>AgentSessionList</code></p></blockquote><p><strong><code>Internal</code></strong></p><p>Built by <code>watchAgentSessions</code>.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="host" tabindex="-1">host <a class="header-anchor" href="#host" aria-label="Permalink to “host”">​</a></h5><p><a href="./../interfaces/AgentSessionListHost.html"><code>AgentSessionListHost</code></a></p><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p><a href="./../interfaces/WatchAgentSessionsOptions.html"><code>WatchAgentSessionsOptions</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>AgentSessionList</code></p><h2 id="accessors" tabindex="-1">Accessors <a class="header-anchor" href="#accessors" aria-label="Permalink to “Accessors”">​</a></h2><h3 id="hasmore" tabindex="-1">hasMore <a class="header-anchor" href="#hasmore" aria-label="Permalink to “hasMore”">​</a></h3><h4 id="get-signature" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>hasMore</strong>(): <code>boolean</code></p></blockquote><p>Whether a further page remains (<code>loadMore()</code>).</p><h5 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h5><p><code>boolean</code></p><hr><h3 id="items" tabindex="-1">items <a class="header-anchor" href="#items" aria-label="Permalink to “items”">​</a></h3><h4 id="get-signature-1" tabindex="-1">Get Signature <a class="header-anchor" href="#get-signature-1" aria-label="Permalink to “Get Signature”">​</a></h4><blockquote><p><strong>get</strong> <strong>items</strong>(): <a href="./../interfaces/AgentSessionWatchedItem.html"><code>AgentSessionWatchedItem</code></a>[]</p></blockquote><p>The loaded sessions, newest activity first.</p><h5 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h5><p><a href="./../interfaces/AgentSessionWatchedItem.html"><code>AgentSessionWatchedItem</code></a>[]</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="close" tabindex="-1">close() <a class="header-anchor" href="#close" aria-label="Permalink to “close()”">​</a></h3><blockquote><p><strong>close</strong>(): <code>void</code></p></blockquote><p>Stop listening: nothing changes after this and no listener is called.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="loadmore" tabindex="-1">loadMore() <a class="header-anchor" href="#loadmore" aria-label="Permalink to “loadMore()”">​</a></h3><blockquote><p><strong>loadMore</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Load the next page; answers at once, with no request, when there is none.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="onchange" tabindex="-1">onChange() <a class="header-anchor" href="#onchange" aria-label="Permalink to “onChange()”">​</a></h3><blockquote><p><strong>onChange</strong>(<code>listener</code>): () =&gt; <code>void</code></p></blockquote><p>Listen for changes to <code>items</code> or <code>hasMore</code>. Calls are coalesced, at most one per macrotask.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="listener" tabindex="-1">listener <a class="header-anchor" href="#listener" aria-label="Permalink to “listener”">​</a></h5><p>() =&gt; <code>void</code></p><p>Called after each change</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p>A function that removes the listener</p><p>() =&gt; <code>void</code></p><hr><h3 id="refresh" tabindex="-1">refresh() <a class="header-anchor" href="#refresh" aria-label="Permalink to “refresh()”">​</a></h3><blockquote><p><strong>refresh</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Read the loaded pages again and merge each item with what the change events already said: the later of each instant, the dot recomputed from them, the status of whichever is newer, and the title, scope and role as listed. A session no longer in those pages leaves the list. The list also refreshes itself after every reconnect. A call while a refresh runs makes one more after it.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="start" tabindex="-1">start() <a class="header-anchor" href="#start" aria-label="Permalink to “start()”">​</a></h3><blockquote><p><strong>start</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p><strong><code>Internal</code></strong></p><p>Subscribe, then read the first page.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p>',67)])])}const m=a(o,[["render",n]]);export{g as __pageData,m as default};
